  y: 0, previousY: 0, vy: 0, grounded: true, low: false,
  jumps: 0, jumpOrigin: 0, rollTime: 0, action: 'run', actionTime: 0,
  airAction: 'ground', state: 'grounded',
  mode: 'running', disjoint: false, rejoinPending: false,
